import {api} from './api.mjs';
import {layout,queueView,postsView,settingsView,detailView,candidateView,welcome} from './views.mjs';
import {esc,icon,btn,formLink} from './ui.mjs';
import {composePostText,cleanUrl} from './domain.mjs';
import {blankDraft,loadDraft,saveDraft,clearDraft,loadPost,savePostDraft,mergeRows,loadWindow} from './state-storage.mjs';
import {teamView,operationsView} from './workspace-views.mjs';
import {queueQuery,beginCandidateEdit,rebaseCandidateEdit,editableCandidate,blankPost,editPost,captureInteraction,restoreInteraction} from './interaction-state.mjs';
import {candidateText} from './candidate-view.mjs';
const $=q=>document.querySelector(q),params=new URLSearchParams(location.search);
const storage={getItem(k){try{return localStorage.getItem(k);}catch{return null;}},setItem(k,v){try{localStorage.setItem(k,v);}catch{}},removeItem(k){try{localStorage.removeItem(k);}catch{}}};
const state={uiLocale:storage.getItem('sneg:locale')||'ru',view:['posts','settings','team','operations'].includes(params.get('view'))?params.get('view'):'review',user:null,connections:{},campaign:{},stats:{},rows:[],total:0,hasMore:false,offset:0,bucket:params.get('bucket')||'all_new',direction:'',search:'',detail:null,mine:[],posts:[],busy:false,step:1,draft:blankDraft(),postDraft:{text:'',includeForm:true,scheduledAt:''}};
let debounce,generation=0,returnFocus,loadedIdentity="",loadedDraft="";
const template='Ищем креаторов для бартера 🇰🇿\n\nSNEG — полоски для домашнего отбеливания зубов. Отправим набор, от вас — честные вертикальные ролики с применением и результатом.\n\nБольшой блог для UGC не нужен. Если хотите публиковать у себя, рассмотрим охваты отдельно.\n\nАлматы, Астана, Шымкент и ещё 13 городов.';
const notes=new Map();
const tr=value=>state.user?.role==='candidate'?candidateText(value,state.uiLocale):value;
function toast(message,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=tr(message);$('#toasts').append(t);setTimeout(()=>t.remove(),6500);}
function show(){document.documentElement.lang=state.user?.role==='candidate'&&state.uiLocale==='kk'?'kk':'ru';const focusedTab=document.activeElement?.getAttribute('role')==='tab'?document.activeElement.dataset.bucket:null,y=window.scrollY;$('#app').innerHTML=layout(state,api.demo||api.localDemo);$('#main').innerHTML=state.user.role==='candidate'?candidateView(state):state.view==='posts'?postsView(state):state.view==='settings'?settingsView(state):state.view==='team'?teamView(state):state.view==='operations'?operationsView(state):queueView(state);if(state.detail)overlays();window.scrollTo(0,y);if(focusedTab)document.querySelector('[data-bucket="'+focusedTab+'"]')?.focus();}
function overlays(){const root=$('#overlay'),snapshot=captureInteraction(root),oldId=root.querySelector('[data-note-id]')?.dataset.noteId,note=root.querySelector('[data-form="note"] textarea');if(oldId&&note)notes.set(oldId,note.value);document.body.classList.toggle('drawer-open',!!state.detail);$('#app').inert=!!state.detail;root.innerHTML=detailView(state);if(state.detail){const input=root.querySelector('[data-form="note"] textarea');if(input)input.value=notes.get(state.detail.id)||'';if(oldId===state.detail.id)restoreInteraction(root,snapshot);else $('.drawer-top button')?.focus();}}
function closeDetail(){const id=state.detail?.id;state.detail=null;overlays();if(state.queueScroll!==undefined)window.scrollTo(0,state.queueScroll);if(returnFocus?.isConnected)returnFocus.focus();else if(id)document.querySelector('[data-detail="'+id+'"]')?.focus();window.Telegram?.WebApp?.BackButton?.hide();}
function modal(title,content,formName='confirm',extra=''){const d=document.createElement('dialog');d.className='modal';d.setAttribute('aria-labelledby','modal-title');d.innerHTML=`<div class="modal-head"><button class="icon-button" data-close-modal aria-label="${esc(tr('Закрыть'))}">${icon('close')}</button></div><h2 id="modal-title">${title}</h2><form data-form="${formName}" ${extra} class="stack">${content}<p class="form-error" role="alert"></p></form>`;document.body.append(d);d.addEventListener('close',()=>d.remove());d.showModal();return d;}
function closeModal(){$('dialog')?.close();}
async function run(fn,form){if(state.busy)return;state.busy=true;document.body.classList.add('busy');const submit=form?.querySelector('button[type="submit"]');const submits=[...(form?.querySelectorAll('button[type="submit"]')||[])];for(const b of submits){b.dataset.idleLabel=b.textContent;b.disabled=true;b.textContent=tr('Сохраняем…');}try{await fn();}catch(e){if(['VERSION_CONFLICT','STATE_CONFLICT'].includes(e.code)&&state.editing){state.mine=(await api.mine()).applications;state.editingConflict=true;persistDraft();show();}if(e.code==='VERSION_CONFLICT'&&['publish','post','resolve-post','schedule-post'].includes(form?.dataset.form)){closeModal();await refresh();toast('Пост изменён в другом окне. Проверьте актуальный текст и подтвердите действие заново.',true);}if(e.code==='CONDITIONS_CHANGED'){state.draft.terms=false;state.draft.consent=false;await refresh().catch(()=>{});persistDraft();toast(e.message,true);}if(e.code==='VERSION_CONFLICT'&&state.detail){state.detail=(await api.detail(state.detail.id)).application;overlays();if(form?.isConnected){form.dataset.version=state.detail.version;const submitAgain=form.querySelector('[type=submit]');if(submitAgain)submitAgain.textContent='Подтвердить по обновлённым данным';}}if(form?.isConnected&&form.querySelector('.form-error'))form.querySelector('.form-error').textContent=tr(e.message);else toast(e.message,true);}finally{state.busy=false;document.body.classList.remove('busy');for(const b of submits)if(b.isConnected){b.disabled=false;b.textContent=b.dataset.idleLabel||b.textContent;}}}
function queueParams(){return queueQuery(state);}
function clearIdentity(){closeModal();state.user=null;state.mine=[];state.rows=[];state.detail=null;state.posts=[];state.campaign={};state.stats={};state.search='';state.direction='';state.offset=0;state.bucket='all_new';state.editing=false;state.editingId=null;state.editingVersion=null;state.editingBase=null;notes.clear();loadedIdentity='';loadedDraft='';state.draft=blankDraft();state.postDraft={text:'',includeForm:true,scheduledAt:''};$('#overlay').replaceChildren();$('#app').inert=false;document.body.classList.remove('drawer-open');}
async function refresh(more=false){
 const seq=++generation;let identity;
 try{identity=await api.session();}catch(e){if(seq!==generation)return;if(e.status===401){clearIdentity();$('#app').innerHTML=welcome(state);}throw e;}
 if(seq!==generation)return;
 if(state.user&&(state.user.id!==identity.user.id||state.user.role!==identity.user.role))clearIdentity();
 state.user=identity.user;state.connections=identity.connections;state.botUsername=identity.botUsername;
 if(loadedIdentity!==state.user.id){loadedIdentity=state.user.id;state.postDraft=loadPost(storage,state.user.id)||{text:'',includeForm:true,scheduledAt:''};}
 if(state.user.role==='candidate'){
  const [mine,campaign]=await Promise.all([api.mine(),api.campaign()]);if(seq!==generation)return;
  const old=state.campaign,changed=old.id&&(old.briefVersion!==campaign.campaign.briefVersion||old.consentVersion!==campaign.campaign.consentVersion);
  const oldMine=state.mine[0],hadForm=!!$('[data-form="application"]'),hadAnswer=!!$('[data-form="answer"]');
  state.mine=mine.applications;state.campaign=campaign.campaign;
  const draftKey=state.user.id+':'+state.campaign.id;
  if(loadedDraft!==draftKey){const restored=loadDraft(storage,state.user.id,state.campaign);state.draft=restored.draft;state.step=restored.step;state.editing=!!restored.draft._editingId&&state.mine[0]?.id===restored.draft._editingId;state.editingId=restored.draft._editingId;state.editingVersion=restored.draft._editingVersion;state.editingBase=restored.draft._editingBase;state.editingConflict=state.editing&&state.mine[0]?.version!==state.editingVersion;loadedDraft=draftKey;}
  if(changed){state.draft.terms=false;state.draft.consent=false;persistDraft();toast('Условия обновились. Прочитайте их и подтвердите согласие ещё раз.',true);}
  if(state.editing&&state.mine[0]?.version!==state.editingVersion)state.editingConflict=true;
  if(hadForm&&!state.editingConflict&&!changed&&state.campaign.ready&&state.campaign.active&&(!state.mine.length||state.editing))return;
  if(hadAnswer&&state.mine[0]?.status==='clarification'&&state.mine[0]?.version===oldMine?.version&&!changed)return;
  show();return;
 }
 const publish=state.user.role==='admin'||state.user.permissions?.publish;
 if(state.view==='posts'&&!publish||['settings','team','operations'].includes(state.view)&&state.user.role!=='admin')state.view='review';
 const target=more?state.rows.length+40:Math.max(40,state.rows.length);
 const q=queueParams();
 const [stats,list,campaign,posts,connections,detail,team,operations]=await Promise.all([
  api.overview(),loadWindow(query=>api.list(query),q,target),api.campaign(),publish?api.posts():{posts:[]},api.connections(),
  state.detail?api.detail(state.detail.id):null,state.view==='team'?api.team():null,state.view==='operations'?api.operations():null
 ]);
 if(seq!==generation)return;
 const oldVersion=state.detail?.version;
 state.stats=stats;state.rows=list.applications;state.total=list.total;state.hasMore=list.hasMore;state.offset=0;
 state.campaign=campaign.campaign;state.posts=posts.posts;state.connections=connections.connections;
 if(detail)state.detail=detail.application;if(team)state.team=team;if(operations)state.operations=operations;
 if(detail&&oldVersion!==detail.application.version)toast('Карточка обновлена. Проверьте новые данные.');
 show();
}

async function openDetail(id){state.queueScroll=window.scrollY;returnFocus=document.activeElement;await run(async()=>{state.detail=(await api.detail(id)).application;overlays();const back=window.Telegram?.WebApp?.BackButton;back?.show();});}
function decision(action,id){const a=state.detail;if(!a||a.id!==id)return;let content,title;if(action==='approve'){title='Выбрать '+esc(a.name)+'?';content=`<p>Кандидат получит приглашение в Telegram. Детали передачи товара вы согласуете лично.</p>${a.portfolio.length?'<label class="check-line"><input type="checkbox" name="portfolioReviewed" required>Работу посмотрел(а), кандидат подходит под бриф</label>':''}${btn('Выбрать кандидата','type="submit"','primary full','check')}`;}else if(action==='clarify'){title='Уточнение';content=`<label>Что нужно уточнить?<textarea name="question" rows="4" minlength="5" required placeholder="Например: пришлите один разговорный ролик с крупным планом.">${esc(a.evaluation?.ai?.question||'')}</textarea></label><p class="fine">Вопрос придёт кандидату в боте. Ответ вернётся в эту карточку.</p>${btn('Отправить вопрос','type="submit"','primary full','arrow')}`;}else if(action==='reject'){title='Пропустить кандидата?';content=`<label>Причина для истории<select name="reason"><option>Не подходит под текущий бриф</option><option>Нужно больше опыта</option><option>Не подходит география</option><option>Уже выбрали нужное количество</option></select></label><p class="fine">Анкета останется в истории. Вы сможете вернуться к ней.</p>${btn('Пропустить','type="submit"','primary full')}`;}else if(action==='mark_sent'){title='Товар уже отправлен?';content=`<p>Это простая отметка менеджера. Доставку вы организуете привычным способом.</p><label class="check-line"><input type="checkbox" name="confirmed" required>Да, товар отправлен этому кандидату</label>${btn('Сохранить отметку','type="submit"','primary full','check')}`;}else{run(async()=>{await api.action(id,action,{},a.version);closeDetail();await refresh();});return;}modal(title,content,'decision',`data-action="${action}" data-id="${id}" data-version="${a.version}"`);}
function persistDraft(){if(state.user&&state.campaign.id)saveDraft(storage,state.user.id,state.campaign,{...state.draft,_editingId:state.editing?state.editingId:null,_editingVersion:state.editing?state.editingVersion:null,_editingBase:state.editing?state.editingBase:null},state.step);}
function startPost(next){if(state.postDraft.dirty){state.pendingPost=next;modal('Закрыть несохранённый текст?',`<p>Текущие правки будут заменены.</p>${btn('Продолжить редактирование','type="button" data-close-modal','secondary')}${btn('Заменить текст','type="submit"','primary')}`,'replace-post');return;}state.postDraft=next;persistPost();show();$('.post-editor textarea')?.focus();}
function persistPost(){if(state.user)savePostDraft(storage,state.user.id,state.postDraft);}
function validatePortfolio(form){const input=form.elements.portfolio;if(!input)return;let error='';try{const links=input.value.split(/\n+/).filter(v=>v.trim());if(links.length>3)throw Error('Добавьте не больше трёх ссылок');for(const link of links)cleanUrl(link);}catch(e){error=tr(e.message);}input.setCustomValidity(error);input.setAttribute('aria-invalid',String(!!error));let hint=form.querySelector('[data-portfolio-error]');if(!hint){hint=document.createElement('small');hint.dataset.portfolioError='';hint.className='field-error';input.after(hint);}hint.textContent=error;}
async function savePostPayload(payload){await api.savePost(payload);state.postDraft=blankPost();persistPost();await refresh();toast(payload.status==='scheduled'?'Публикация поставлена в расписание.':'Черновик сохранён.');}
function updatePostPreview(form){const marker=$('[data-post-dirty]');if(marker)marker.textContent=state.postDraft.dirty?'Есть несохранённые изменения':'';const content=composePostText(form.elements.text.value,formLink(state.botUsername),form.elements.includeForm.checked),count=[...content].length;form.elements.text.setCustomValidity(count>500?'Вместе со ссылкой получается '+count+' символов. Сократите до 500.':count<10?'Напишите хотя бы 10 символов.':'');const label=$('[data-post-count]');if(label){label.textContent=count+' / 500';label.classList.toggle('field-error',count>500);}const preview=$('[data-post-preview]');if(preview)preview.textContent=content;}
function collectDraft(form){const f=new FormData(form);for(const[k,v]of f)if(k!=='directions')state.draft[k]=v;if(state.step===1)state.draft.directions=f.getAll('directions');else for(const k of ['adult','closeup','terms','consent','audienceKz'])state.draft[k]=f.has(k);}
function connectGuard(){if(api.demo||api.localDemo){toast('Подключения доступны в рабочем кабинете Telegram.',true);return false;}return true;}
document.addEventListener('click',async event=>{
 const t=event.target.closest('button,a');if(!t)return;if(t.hasAttribute('data-close-modal')){closeModal();return;}if(t.hasAttribute('data-close-detail')){closeDetail();return;}
 if(t.dataset.locale){state.uiLocale=t.dataset.locale;storage.setItem('sneg:locale',state.uiLocale);show();return;}
 if(t.hasAttribute('data-account')){const u=state.user,role=u.role==='candidate'?'Кандидат':u.role==='admin'?'Владелец · менеджер':'Менеджер';modal(tr('Аккаунт'),`<dl class="account-details"><div><dt>${tr('Имя')}</dt><dd>${esc(u.name||'—')}</dd></div>${u.username?'<div><dt>Telegram</dt><dd>@'+esc(u.username)+'</dd></div>':''}<div><dt>${tr('Доступ')}</dt><dd>${role}</dd></div><div><dt>Telegram ID</dt><dd>${esc(u.id)}</dd></div></dl>${btn(tr('Закрыть'),'type="button" data-close-modal','secondary full')}`,'account');return;}
 if(t.hasAttribute('data-clear-search')){state.search='';state.offset=0;state.rows=[];await run(()=>refresh());return;}
 if(t.dataset.view){state.view=t.dataset.view;closeDetail();history.replaceState(null,'','/?view='+state.view);await run(()=>refresh());return;}
 if(t.dataset.bucket){state.bucket=t.dataset.bucket;state.offset=0;state.rows=[];await run(()=>refresh());return;}
 if(t.dataset.detail){await openDetail(t.dataset.detail);return;}
 if(t.dataset.decision){decision(t.dataset.decision,t.dataset.id);return;}
 if(t.hasAttribute('data-demo-work')){event.preventDefault();toast('Это вымышленная анкета. В рабочем наборе здесь открывается настоящий ролик кандидата.');return;}
 if(t.hasAttribute('data-role-switch')){api.setCandidate(state.user.role!=='candidate');await run(async()=>{const session=await api.session();state.user=session.user;await refresh();});return;}
 if(t.hasAttribute('data-refresh')){await run(()=>refresh());return;}
 if(t.hasAttribute('data-more')){await run(()=>refresh(true));return;}
 if(t.hasAttribute('data-form-back')){collectDraft(t.closest('form'));state.step=1;persistDraft();show();return;}
 if(t.hasAttribute('data-post-template')){startPost({ ...blankPost(),text:template,dirty:true});return;}
 if(t.hasAttribute('data-new-post')){startPost(blankPost());return;}
 if(t.hasAttribute('data-reset-filter')){const key=t.dataset.resetFilter;if(key==='owner')state.ownerFilter='';if(key==='direction')state.direction='';if(key==='recommended')state.bucket='all_new';state.rows=[];await run(()=>refresh());return;}
 if(t.dataset.editPost){const p=state.posts.find(p=>p.id===t.dataset.editPost);if(p)startPost(editPost(p));return;}
 if(t.dataset.publish){if(!state.connections.threads){toast('Сначала подключите Threads.',true);return;}const p=state.posts.find(p=>p.id===t.dataset.publish);modal('Опубликовать сейчас?',`<p>Аккаунт: <strong>@${esc(state.connections.threadsUsername||'Threads')}</strong></p><div class="publication-confirmation">${esc(p.text)}</div>${btn('Опубликовать этот текст','type="submit"','primary full','arrow')}`,'publish',`data-id="${p.id}" data-version="${p.version||1}" data-account="${esc(state.connections.threadsAccountId)}"`);return;}
 if(t.dataset.cancelPost){await run(async()=>{const p=state.posts.find(p=>p.id===t.dataset.cancelPost);await api.postAction(p.id,'cancel',p.version||1);await refresh();toast('Пост возвращён в черновики.');});return;}
 if(t.hasAttribute('data-authorize')){if(!connectGuard())return;await run(async()=>{const r=await api.integrate('threads/authorize',{});if(window.Telegram?.WebApp?.openLink)window.Telegram.WebApp.openLink(r.url,{try_instant_view:false});else location.href=r.url;});return;}
 if(t.hasAttribute('data-disconnect')){modal('Отключить Threads?',`<p>Новые публикации остановятся. Черновики сохранятся.</p>${btn('Отключить','type="submit"','primary full')}`,'disconnect');return;}
 if(t.dataset.member||t.dataset.revoke){const id=t.dataset.member||t.dataset.revoke,m=state.team.members.find(m=>m.id===id);modal(t.dataset.revoke?'Отозвать доступ?':'Права менеджера',`<p>${esc(m.name)} · ${esc(id)}</p>${t.dataset.revoke?'':`<label class="check-line"><input type="checkbox" name="publish" ${m.publish?'checked':''}>Разрешить публикации Threads</label>`}<label class="check-line"><input type="checkbox" name="confirmed" required>Подтверждаю изменение доступа</label>${btn('Сохранить','type="submit"','primary')}`,'member-update',`data-id="${id}" data-active="${t.dataset.revoke?'false':'true'}"`);return;}
 if(t.hasAttribute('data-ai-disable')){await run(async()=>{await api.integrate('ai',{provider:'rules'});await refresh();});return;}
 if(t.hasAttribute('data-shortlist')){await run(async()=>{await api.shortlist();toast('Подборка появится в Telegram после обработки очереди.');});return;}
 if(t.hasAttribute('data-edit-application')){const a=state.mine[0];Object.assign(state,beginCandidateEdit(a));if(a.briefVersion!==state.campaign.briefVersion||a.consentVersion!==state.campaign.consentVersion){state.draft.terms=false;state.draft.consent=false;}state.step=1;persistDraft();show();return;}
 if(t.hasAttribute('data-cancel-edit')){state.editing=false;state.editingId=null;state.editingVersion=null;state.editingConflict=false;clearDraft(storage,state.user.id,state.campaign);loadedDraft='';show();return;}
 if(t.hasAttribute('data-rebase-edit')){if(!editableCandidate(state.mine[0]))return;Object.assign(state,rebaseCandidateEdit(state.editingBase,state.draft,state.mine[0]));persistDraft();show();toast('Ваши правки перенесены. Проверьте анкету перед сохранением.');return;}
 if(t.hasAttribute('data-reload-edit')){state.savedCandidateDraft=structuredClone(state.draft);Object.assign(state,beginCandidateEdit(state.mine[0]));persistDraft();show();return;}
 if(t.hasAttribute('data-withdraw')){modal(tr('Отозвать анкету?'),`<p>${tr('Менеджер увидит, что вы больше не участвуете в этом наборе.')}</p>${btn(tr('Отозвать анкету'),'type="submit"','primary')}`,'withdraw');return;}
 if(t.dataset.claim||t.dataset.release){await run(async()=>{const a=state.detail;await api.action(a.id,t.dataset.release?'release':'claim',{},a.version);state.detail=(await api.detail(a.id)).application;await refresh();});return;}
 if(t.dataset.retryAi){await run(async()=>{await api.retryAI(t.dataset.retryAi);await refresh();toast('Оценка поставлена в очередь.');});return;}
 if(t.dataset.resolvePost){modal('Проверка публикации',`<p>Сначала откройте подключённый профиль Threads и проверьте пост.</p><label>Результат<select name="outcome"><option value="published">Пост опубликован</option><option value="absent">Публикации нет — вернуть в черновики</option></select></label><label>Ссылка на опубликованный пост<input name="permalink" type="url" placeholder="https://www.threads.com/…"></label><label class="check-line"><input type="checkbox" name="confirmed" required>Профиль проверен, подтверждаю результат</label>${btn('Сохранить результат','type="submit"','primary')}`,'resolve-post',`data-id="${t.dataset.resolvePost}" data-version="${state.posts.find(p=>p.id===t.dataset.resolvePost)?.version||1}"`);return;}
 if(t.hasAttribute('data-backup')){await run(async()=>{await api.backup();await refresh();toast('Копия проверена и сохранена.');});return;}
 if(t.dataset.download){await run(()=>api.download(t.dataset.download));return;}
 if(t.dataset.retryJob){modal('Повторить задание?',`<p>Проверьте, не было ли уже получено сообщение: после сбоя связи повтор может отправить его ещё раз.</p><label class="check-line"><input type="checkbox" name="confirmed" required>Проверил(а), повтор нужен</label>${btn('Повторить','type="submit"','primary')}`,'retry-job',`data-id="${t.dataset.retryJob}"`);return;}

 if(t.hasAttribute('data-copy')){if(!t.dataset.copy){toast('Адрес появится в рабочем кабинете Telegram.',true);return;}try{await navigator.clipboard.writeText(t.dataset.copy);toast('Адрес скопирован.');}catch{toast('Выделите адрес и скопируйте его вручную.',true);}return;}
});
document.addEventListener('click',e=>{if(e.target.classList.contains('drawer-backdrop'))closeDetail();});
document.addEventListener('input',e=>{const t=e.target;if(t.closest('[data-form="note"]')&&state.detail)notes.set(state.detail.id,t.value);if(t.hasAttribute('data-search')){state.search=t.value;state.offset=0;clearTimeout(debounce);debounce=setTimeout(async()=>{const seq=++generation;try{const list=await api.list(queueParams());if(seq!==generation)return;state.rows=list.applications;state.total=list.total;state.hasMore=list.hasMore;const focus=t.selectionStart;show();const input=$('[data-search]');input?.focus();input?.setSelectionRange(focus,focus);}catch(err){toast(err.message,true);}},300);}if(t.closest('[data-form="application"]')){collectDraft(t.closest('form'));persistDraft();validatePortfolio(t.closest('form'));}if(t.closest('[data-form="post"]')){const f=t.closest('form');state.postDraft={...state.postDraft,dirty:true,operationId:undefined,text:f.elements.text.value,includeForm:f.elements.includeForm.checked,scheduledAt:f.elements.scheduledAt.value};persistPost();updatePostPreview(f);}});
document.addEventListener('toggle',e=>{if(e.target.classList?.contains('filter-menu'))state.filtersOpen=e.target.open;},true);
document.addEventListener('invalid',e=>{if(state.user?.role==='candidate'&&state.uiLocale==='kk'&&e.target.setCustomValidity&&!e.target.validity.customError)e.target.setCustomValidity(tr(e.target.validity.valueMissing?'Заполните это поле':'Проверьте значение поля'));},true);
document.addEventListener('input',e=>{if(e.target.setCustomValidity&&e.target.closest('[data-form="application"],[data-form="answer"]')){e.target.setCustomValidity('');if(e.target.name==='portfolio')validatePortfolio(e.target.closest('form'));}});
document.addEventListener('change',async e=>{if(e.target.closest('[data-form="application"]')){collectDraft(e.target.closest('form'));persistDraft();}if(e.target.hasAttribute('data-owner-filter')){state.ownerFilter=e.target.tagName==='SELECT'?e.target.value:e.target.checked?'mine':'';state.rows=[];await run(()=>refresh());}if(e.target.hasAttribute('data-recommended')){state.bucket=e.target.checked?'recommended':'all_new';state.rows=[];await run(()=>refresh());}if(e.target.closest('[data-form="post"]')){const f=e.target.closest('form');state.postDraft={...state.postDraft,dirty:true,operationId:undefined,text:f.elements.text.value,includeForm:f.elements.includeForm.checked,scheduledAt:f.elements.scheduledAt.value};persistPost();updatePostPreview(f);}if(e.target.hasAttribute('data-direction')){state.direction=e.target.value;state.offset=0;state.rows=[];await run(()=>refresh());}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const kind=form.dataset.form,f=new FormData(form);if(kind==='application'&&state.step===1){collectDraft(form);if(!state.draft.directions.length){form.querySelector('.form-error').textContent=tr('Выберите хотя бы один формат.');return;}state.step=2;persistDraft();show();window.scrollTo(0,0);return;}
 run(async()=>{
  if(kind==='application'){collectDraft(form);const data={...state.draft,briefVersion:state.campaign.briefVersion,consentVersion:state.campaign.consentVersion,portfolio:String(state.draft.portfolio||'').split(/\n+/).filter(Boolean),views:state.draft.views||null,followers:state.draft.followers||null};if(state.editing){if(state.editingConflict)throw Error('Анкета изменилась. Сначала сравните правки с актуальными данными.');await api.action(state.editingId,'edit',data,state.editingVersion);}else await api.submit(data);clearDraft(storage,state.user.id,state.campaign);state.draft=blankDraft();state.editing=false;state.editingId=null;state.editingVersion=null;state.editingConflict=false;loadedDraft='';await refresh();window.scrollTo(0,0);toast('Анкета отправлена.');}
  if(kind==='replace-post'){state.postDraft=state.pendingPost;state.pendingPost=null;closeModal();persistPost();show();$('.post-editor textarea')?.focus();}
  if(kind==='answer'){const a=state.mine[0];await api.action(a.id,'answer',{answer:f.get('answer')},a.version);await refresh();toast('Ответ передан менеджеру.');}
  if(kind==='decision'){const action=form.dataset.action,payload=Object.fromEntries(f);if(action==='approve')payload.portfolioReviewed=true;if(action==='mark_sent')payload.confirmed=f.has('confirmed');await api.action(form.dataset.id,action,payload,Number(form.dataset.version));closeModal();closeDetail();await refresh();toast('Решение сохранено.');if(['approve','reject','reserve'].includes(action)){const next=state.rows.find(a=>a.status==='review'&&a.id!==form.dataset.id);if(next){state.detail=(await api.detail(next.id)).application;overlays();window.Telegram?.WebApp?.BackButton?.show();}}}
  if(kind==='post'){updatePostPreview(form);if(!form.reportValidity())return;const intent=event.submitter?.value||'draft',signature=JSON.stringify({id:state.postDraft.id,text:f.get('text'),includeForm:f.has('includeForm'),status:intent,accountId:state.connections.threadsAccountId,scheduledAt:f.get('scheduledAt')});if(state.postDraft.operationSignature!==signature)state.postDraft.operationId=undefined;state.postDraft.operationSignature=signature;state.postDraft.operationId=state.postDraft.operationId||crypto.randomUUID();persistPost();const payload={id:state.postDraft.id,version:state.postDraft.version,operationId:state.postDraft.operationId,text:f.get('text'),includeForm:f.has('includeForm'),status:intent,accountId:state.connections.threadsAccountId,scheduledAt:f.get('scheduledAt')?new Date(f.get('scheduledAt')).toISOString():null};if(intent==='scheduled'){if(!payload.scheduledAt||Date.parse(payload.scheduledAt)<=Date.now())throw Error('Выберите время публикации в будущем.');state.pendingSchedule=payload;modal('Запланировать публикацию?',`<p><strong>@${esc(state.connections.threadsUsername||'Threads')}</strong> · ${esc(new Date(payload.scheduledAt).toLocaleString('ru-RU'))}</p><div class="publication-confirmation">${esc(composePostText(payload.text,formLink(state.botUsername),payload.includeForm))}</div>${btn('Запланировать этот текст','type="submit"','primary')}`,'schedule-post');return;}await savePostPayload(payload);}
  if(kind==='schedule-post'){await savePostPayload(state.pendingSchedule);state.pendingSchedule=null;closeModal();}
  if(kind==='publish'){await api.postAction(form.dataset.id,'publish',Number(form.dataset.version),form.dataset.account);closeModal();await refresh();toast('Пост передан в очередь публикации.');}
  if(kind==='campaign'){await api.updateCampaign({...Object.fromEntries(f),limit:Number(f.get('limit')),minViews:Number(f.get('minViews')),active:f.has('active'),productionApproved:f.has('productionApproved'),retentionDays:Number(f.get('retentionDays')||180),retentionEnabled:f.has('retentionEnabled')});await refresh();toast('Условия сохранены.');}
  if(kind==='threads-app'||kind==='threads-token'){if(!connectGuard())return;await api.integrate(kind==='threads-app'?'threads/app':'threads/token',Object.fromEntries(f));form.reset();await refresh();toast(kind==='threads-app'?'Приложение сохранено. Теперь нажмите «Войти в Threads».':'Аккаунт Threads подключён.');}
  if(kind==='ai'){if(!connectGuard())return;toast('Проверяем ключ и ответ модели…');await api.integrate('ai',{...Object.fromEntries(f),provider:'gemini'});form.reset();await refresh();toast('ИИ подключён. Новые анкеты будут получать резюме.');}
  if(kind==='member'){await api.saveMember({...Object.fromEntries(f),active:true,publish:f.has('publish'),confirmed:f.has('confirmed')});form.reset();await refresh();toast('Менеджер добавлен. Пусть отправит боту /start.');}
  if(kind==='member-update'){const m=state.team.members.find(m=>m.id===form.dataset.id);await api.saveMember({...m,active:form.dataset.active==='true',publish:f.has('publish'),confirmed:f.has('confirmed')});closeModal();await refresh();toast('Доступ обновлён.');}
  if(kind==='resolve-post'){await api.resolvePost(form.dataset.id,{...Object.fromEntries(f),confirmed:f.has('confirmed'),version:Number(form.dataset.version)});closeModal();await refresh();toast('Результат проверки сохранён.');}
  if(kind==='retry-job'){await api.retryJob(form.dataset.id,f.has('confirmed'));closeModal();await refresh();toast('Задание поставлено в очередь.');}
  if(kind==='withdraw'){const a=state.mine[0];await api.action(a.id,'withdraw',{},a.version);closeModal();await refresh();}
  if(kind==='note'){const a=state.detail;await api.action(a.id,'note',{note:f.get('note')},a.version);notes.delete(a.id);const noteInput=$('[data-form="note"] textarea');if(noteInput)noteInput.value='';state.detail=(await api.detail(a.id)).application;overlays();toast('Внутренняя заметка сохранена.');}

  if(kind==='disconnect'){await api.integrate('threads/disconnect',{});closeModal();await refresh();toast('Threads отключён.');}
 },form);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog'))closeDetail();if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const tabs=[...document.querySelectorAll('[role=tab]')];const i=tabs.indexOf(document.activeElement);if(i>=0){e.preventDefault();const next=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];next?.focus();next?.click();}}if(e.key==='Tab'&&state.detail&&!$('dialog')){const focusable=[...$('.drawer').querySelectorAll('a,button,input,textarea,select,summary')].filter(el=>!el.disabled&&el.getClientRects().length);if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===focusable.at(-1)){e.preventDefault();focusable[0]?.focus();}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.user&&!state.busy&&!$('dialog')&&state.view!=='settings')run(()=>refresh());});
async function boot(){window.Telegram?.WebApp?.ready();window.Telegram?.WebApp?.expand();window.Telegram?.WebApp?.BackButton?.onClick(closeDetail);try{await refresh();const candidate=params.get('candidate');if(candidate&&state.user.role!=='candidate')await openDetail(candidate);}catch(e){if(e.status===401){try{const p=await api.public();state.campaign=p.campaign;state.botUsername=p.botUsername;$('#app').innerHTML=welcome(state);}catch{$('#app').innerHTML='<main class="application-wrap"><h1>Связь прервалась.</h1><p>Откройте приложение из бота ещё раз.</p></main>';}}else{$('#app').innerHTML=`<main class="application-wrap"><h1>Нужен ещё один шаг.</h1><p>${esc(e.message)}</p>${btn('Попробовать снова','data-retry','primary')}</main>`;$('[data-retry]').onclick=()=>location.reload();}}}
window.addEventListener('beforeunload',e=>{if(state.postDraft.dirty||[...notes.values()].some(v=>v.trim())){e.preventDefault();e.returnValue='';}});
let polling=false;
setInterval(async()=>{if(polling||document.hidden||state.busy||$('dialog')||!state.user)return;const id=state.detail?.id,user=state.user.id;polling=true;try{if(id){const r=await api.detail(id);if(state.user?.id!==user||state.detail?.id!==id||state.busy||$('dialog'))return;if(r.application.version!==state.detail.version){state.detail=r.application;overlays();toast('Карточка обновлена. Проверьте новые данные.');}}else if(state.user.role==='candidate'&&state.mine.length&&!state.editing&&!$('[data-form="answer"]')){const mine=await api.mine();if(state.user?.id===user&&!state.busy&&!$('dialog')&&JSON.stringify(mine.applications.map(a=>[a.id,a.version,a.status]))!==JSON.stringify(state.mine.map(a=>[a.id,a.version,a.status])))await refresh();}}catch{}finally{polling=false;}},10000);
boot();
